async function limitedCall(toolName,args,label){
const Policy=eval('('+load('rateClassSource')+')');
const s=load('rateState');const weight=args.actions?.length??1;
let wait=Policy.waitMs(s,weight,Date.now());
while(wait>0){s.log.push({type:'pause',at:new Date().toISOString(),label,waitMs:wait});store('rateState',s);if(wait>3000)notify('Контроль темпу: пауза '+Math.ceil(wait/1000)+' с.');await new Promise(r=>setTimeout(r,Math.min(wait,45000)));wait=Policy.waitMs(s,weight,Date.now());}
const start=Date.now();let result;
try{result=await tools[toolName](args);}catch(e){result={isError:true,exception:String(e)};}
const end=Date.now();Policy.finish(s,weight,end);
const raw=JSON.stringify(result);const is429=/too_many_requests|Too Many Requests|\\"status\\":429|\\"statusCode\\":429|rate.limit.exceeded/i.test(raw);
if(is429){const match=raw.match(/Retry-After[^0-9]*(\\d+)/i);const retry=Policy.rateLimited(s,match?.[1],end);s.log.push({type:'rate_limit',at:new Date(end).toISOString(),...retry});}
s.log.push({type:'call',label,tool:toolName,startedAt:new Date(start).toISOString(),endedAt:new Date(end).toISOString(),weight,durationMs:end-start,is429,isError:!!result.isError,exception:result.exception??null});
store('rateState',s);store('lastWebflowResult',result);if(is429)throw new Error('RATE_LIMIT_RECONCILE_REQUIRED');return result;
}

