async function applyBatch(ops,label){
const call=eval('('+load('limitedCallSource')+')');
const siteId='6899ffe04a85e00f2b8cf5ab',pageId='6899ffe04a85e00f2b8cf5ac';
const scopes=[...new Set(ops.map(o=>o.scope))];if(scopes.length!==1)throw new Error('One scope per batch');
const scope=scopes[0];
const actions=ops.map(o=>({label:o.label,set_text:{id:o.id,text:o.after,...(scope?{scope_component_id:scope}:{})}}));
const write=await call('mcp__codex_apps__webflow_data_element_tool',{siteId,pageId,actions},'write-'+label);
const writes=load('writeResponses')??[];writes.push({label,ops,response:write});store('writeResponses',writes);await eval('('+load('checkpointSource')+')')();
const read=await call('mcp__codex_apps__webflow_data_element_tool',{siteId,pageId,actions:[{label:'Readback '+label,get_all_elements:{depth:-1,...(scope?{scope_component_id:scope}:{})}}]},'readback-'+label);
const parsed=read.content.filter(c=>c.type==='text').map(c=>JSON.parse(c.text));
const tree=parsed[0]?.result?.[0]?.data;if(!tree)throw new Error('Readback unavailable');
const index={};const visit=n=>{index[n.id.element]=n;for(const c of n.children??[])visit(c);};visit(tree);
const checks=ops.map(o=>({label:o.label,field_id:o.field_id,id:o.id,before:o.before,expected:o.after,actual:index[o.id.element]?.textContent,status:index[o.id.element]?.textContent===o.after?'applied':index[o.id.element]?.textContent===o.before?'not-applied':'conflict'}));
store('lastReadTree_'+(scope??pageId),tree);
const batches=load('appliedBatches')??[];batches.push({label,write,checks});store('appliedBatches',batches);
const applied=load('appliedOps')??[];for(const c of checks)if(c.status==='applied'&&!applied.includes(c.label))applied.push(c.label);store('appliedOps',applied);
await eval('('+load('checkpointSource')+')')();
if(checks.some(c=>c.status!=='applied')){text({label,checks,write});throw new Error('Batch reconciliation required');}
text({batch:label,operations:ops.length,verified:checks.length,totalVerified:applied.length});
return checks;
}
